CREATE TABLE IF NOT EXISTS organizations (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('clinician','coordinator','patient','receiver','admin')), patient_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organization_memberships (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), user_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id));
CREATE TABLE IF NOT EXISTS role_assignments (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), user_id text NOT NULL REFERENCES users(id), role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id,role));
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patients (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, birth_date date NOT NULL, language text NOT NULL DEFAULT 'en', synthetic boolean NOT NULL DEFAULT true CHECK(synthetic), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE TABLE IF NOT EXISTS patient_identifiers (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), patient_id text NOT NULL REFERENCES patients(id), system text NOT NULL, value text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,system,value));
CREATE TABLE IF NOT EXISTS patient_contacts (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), patient_id text NOT NULL REFERENCES patients(id), channel text NOT NULL, value text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patient_consents (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), patient_id text NOT NULL REFERENCES patients(id), purpose text NOT NULL, granted boolean NOT NULL, actor_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clinical_policies (id text PRIMARY KEY, organization_id text REFERENCES organizations(id), pathway text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS policy_versions (id text PRIMARY KEY, policy_id text NOT NULL REFERENCES clinical_policies(id), version text NOT NULL, approval_status text NOT NULL, document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(policy_id,version));
CREATE TABLE IF NOT EXISTS fhir_resources (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), source text NOT NULL, resource_type text NOT NULL, source_id text NOT NULL, source_version text NOT NULL, resource jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,source,resource_type,source_id,source_version));
CREATE TABLE IF NOT EXISTS screening_results (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), patient_id text NOT NULL REFERENCES patients(id), source_id text NOT NULL, source text NOT NULL, pathway text NOT NULL, status text NOT NULL, revision integer NOT NULL DEFAULT 1, summary text NOT NULL, issued_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,source,source_id));
CREATE TABLE IF NOT EXISTS observations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), patient_id text NOT NULL REFERENCES patients(id), result_id text REFERENCES screening_results(id), source_resource_id text REFERENCES fhir_resources(id), coding jsonb NOT NULL, value jsonb, effective_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS care_episodes (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), patient_id text NOT NULL REFERENCES patients(id), result_id text NOT NULL REFERENCES screening_results(id), phase text NOT NULL CHECK(phase IN ('RESULT_RECEIVED','CLINICAL_REVIEW','PATIENT_CONTACT','CARE_COORDINATION','OUTCOME_VERIFICATION','CLOSED')), status text NOT NULL CHECK(status IN ('ACTIVE','BLOCKED','OVERDUE','CLOSED','REOPENED')), owner_id text REFERENCES users(id), due_at timestamptz, version integer NOT NULL DEFAULT 1 CHECK(version>0), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,result_id));
CREATE TABLE IF NOT EXISTS episode_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), actor_id text NOT NULL REFERENCES users(id), type text NOT NULL, version integer NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(episode_id,version));
CREATE TABLE IF NOT EXISTS episode_owners (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), owner_id text REFERENCES users(id), requested_by text REFERENCES users(id), status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS episode_tasks (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), type text NOT NULL, title text NOT NULL, status text NOT NULL, due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clinical_reviews (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), clinician_id text NOT NULL REFERENCES users(id), note text NOT NULL, patient_explanation text NOT NULL, policy_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referrals (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), receiving_organization_id text NOT NULL REFERENCES organizations(id), status text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), responded_at timestamptz);
CREATE TABLE IF NOT EXISTS referral_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), referral_id text NOT NULL REFERENCES referrals(id), actor_id text NOT NULL REFERENCES users(id), status text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), referral_id text NOT NULL REFERENCES referrals(id), scheduled_at timestamptz NOT NULL, location text NOT NULL, status text NOT NULL, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS encounters (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), appointment_id text NOT NULL UNIQUE REFERENCES appointments(id), recorded_by text NOT NULL REFERENCES users(id), note text NOT NULL, completed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS communications (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), channel text NOT NULL, content text NOT NULL, status text NOT NULL, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE TABLE IF NOT EXISTS message_attempts (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), communication_id text NOT NULL REFERENCES communications(id), outcome text NOT NULL, attempt integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(communication_id,attempt));
CREATE TABLE IF NOT EXISTS acknowledgements (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL UNIQUE REFERENCES care_episodes(id), patient_id text NOT NULL REFERENCES patients(id), actor_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clinical_documents (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), title text NOT NULL, content text NOT NULL, sha256 text NOT NULL, media_type text NOT NULL DEFAULT 'text/plain', created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_records (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), document_id text NOT NULL REFERENCES clinical_documents(id), kind text NOT NULL, submitted_by text NOT NULL REFERENCES users(id), verified_by text REFERENCES users(id), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS closure_decisions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), clinician_id text NOT NULL REFERENCES users(id), note text NOT NULL, evidence_ids jsonb NOT NULL, policy_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), actor_id text NOT NULL REFERENCES users(id), episode_id text REFERENCES care_episodes(id), action text NOT NULL, request_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS access_grants (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), receiving_organization_id text NOT NULL REFERENCES organizations(id), granted_by text NOT NULL REFERENCES users(id), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(episode_id,receiving_organization_id));
CREATE TABLE IF NOT EXISTS inbox_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), source text NOT NULL, event_id text NOT NULL, fingerprint text NOT NULL, status text NOT NULL, error text, payload jsonb NOT NULL, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,source,event_id));
CREATE TABLE IF NOT EXISTS outbox_events (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS workflow_executions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), actor_id text NOT NULL REFERENCES users(id), episode_id text NOT NULL REFERENCES care_episodes(id), idempotency_key text NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,actor_id,idempotency_key));
CREATE TABLE IF NOT EXISTS model_registry (id text PRIMARY KEY, organization_id text REFERENCES organizations(id), version text NOT NULL, kind text NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_predictions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), model_id text REFERENCES model_registry(id), score double precision NOT NULL CHECK(score>=0 AND score<=1), inputs jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_recommendations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), episode_id text NOT NULL REFERENCES care_episodes(id), actor_id text NOT NULL REFERENCES users(id), response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_evaluations (id text PRIMARY KEY, organization_id text REFERENCES organizations(id), model_id text REFERENCES model_registry(id), metrics jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scenario_runs (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), actor_id text NOT NULL REFERENCES users(id), seed integer NOT NULL, results jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS episodes_tenant_status_idx ON care_episodes(organization_id,status,due_at);
CREATE INDEX IF NOT EXISTS episodes_patient_idx ON care_episodes(organization_id,patient_id);
CREATE INDEX IF NOT EXISTS grants_receiver_idx ON access_grants(receiving_organization_id,episode_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS outbox_due_idx ON outbox_events(status,available_at);
CREATE INDEX IF NOT EXISTS audit_scope_idx ON audit_events(organization_id,created_at);
CREATE INDEX IF NOT EXISTS session_expiry_idx ON sessions(expires_at);
CREATE OR REPLACE FUNCTION deny_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable_record'; END $$;
DROP TRIGGER IF EXISTS episode_events_immutable ON episode_events;
CREATE TRIGGER episode_events_immutable BEFORE UPDATE OR DELETE ON episode_events FOR EACH ROW EXECUTE FUNCTION deny_immutable_mutation();
DROP TRIGGER IF EXISTS audit_events_immutable ON audit_events;
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION deny_immutable_mutation();
DROP TRIGGER IF EXISTS closure_decisions_immutable ON closure_decisions;
CREATE TRIGGER closure_decisions_immutable BEFORE UPDATE OR DELETE ON closure_decisions FOR EACH ROW EXECUTE FUNCTION deny_immutable_mutation();
